package com.sebha.app.data

/**
 * Daily Hijri douʿā entry.
 * Looked up by [hijriMonth] + [hijriDay] — no database table needed.
 *
 * Display rule: Arabic script for the dua itself; meaning/theme follow the
 * app language (fr / en / ar). Never show Latin transliteration.
 */
data class DailyDua(
    val id: Int,
    val hijriDay: Int,
    val hijriMonth: Int,
    val occasion: String,
    val themeFr: String,
    val themeEn: String,
    val themeAr: String,
    val duaAr: String,
    val translationFr: String,
    val translationEn: String,
    val source: String,
    val sourceType: SourceType,
    val favorite: Boolean = false
) {
    fun themeFor(language: String): String = when {
        language.startsWith("ar") -> themeAr
        language.startsWith("en") -> themeEn
        else -> themeFr
    }

    /** Meaning in the UI language; null for Arabic (the dua itself is enough). */
    fun translationFor(language: String): String? = when {
        language.startsWith("ar") -> null
        language.startsWith("en") -> translationEn
        else -> translationFr
    }
}

enum class SourceType {
    QURAN,
    HADITH
}

