            themeAr = "التوكل",
            duaAr = "حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ ۖ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ",
            translationFr = "Allah me suffit. Il n'y a de divinité que Lui. Je place ma confiance en Lui.",
            translationEn = "Allah is sufficient for me. There is no god but Him. I place my trust in Him.",
