            themeFr = "Prière sur le Prophète ﷺ",
            themeEn = "Prayers upon the Prophet ﷺ",
            themeAr = "الصلاة على النبي ﷺ",
            duaAr = "اللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، اللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ",
            translationFr = "Ô Allah, prie sur Muhammad et sur la famille de Muhammad comme Tu as prié sur Ibrahim et sur la famille d'Ibrahim. Tu es Digne de louange, Glorieux. Ô Allah, bénis Muhammad et la famille de Muhammad comme Tu as béni Ibrahim et la famille d'Ibrahim. Tu es Digne de louange, Glorieux.",
            translationEn = "O Allah, send prayers upon Muhammad and upon the family of Muhammad as You sent prayers upon Ibrahim and upon the family of Ibrahim. You are Worthy of praise, Glorious. O Allah, bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim. You are Worthy of praise, Glorious.",
            source = "Sahih al-Bukhari, Sahih Muslim",
            sourceType = SourceType.HADITH
        ),
        DailyDua(
            id = 89,
            hijriDay = 12,
            hijriMonth = 4,
            occasion = "12 Rabîʿ ath-Thânî",
            themeFr = "Demande de pardon",
            themeEn = "Seeking forgiveness",
            themeAr = "طلب المغفرة",
            duaAr = "اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَىٰ عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ",
            translationFr = "Ô Allah, Tu es mon Seigneur, il n'y a de divinité que Toi. Tu m'as créé et je suis Ton serviteur. Je m'en tiens à Ton pacte et à Ta promesse autant que je le peux. Je cherche protection auprès de Toi contre le mal de ce que j'ai fait. Je reconnais Tes bienfaits sur moi et je reconnais mon péché. Pardonne-moi, car nul ne pardonne les péchés sauf Toi. (Sayyid al-Istighfâr)",
            translationEn = "O Allah, You are my Lord, there is no god but You. You created me and I am Your servant. I uphold Your covenant and Your promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your blessings upon me and I acknowledge my sin. Forgive me, for none forgives sins except You. (Sayyid al-Istighfar)",
            source = "Sahih Muslim",
            sourceType = SourceType.HADITH
        ),
