            themeEn = "Protection",
            themeAr = "الحماية",
            duaAr = "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ",
            translationFr = "Dis : Je cherche protection auprès du Seigneur de l'aube contre le mal de ce qu'Il a créé, contre le mal de la nuit quand elle s'étend, contre le mal de celles qui soufflent sur les nœuds, et contre le mal de l'envieux quand il envie.",
            translationEn = "Say: I seek refuge in the Lord of daybreak from the evil of what He has created, from the evil of darkness when it settles, from the evil of those who blow on knots, and from the evil of the envier when he envies.",
            source = "Coran 113",
            sourceType = SourceType.QURAN
        ),
