            translationFr = "Ô Allah, mets une lumière dans mon cœur, dans ma langue, dans mon ouïe, dans ma vue ; au-dessus de moi, au-dessous de moi, à ma droite, à ma gauche, devant moi, derrière moi ; et fais de moi une lumière.",
