            themeFr = "Bonne moralité",
            themeEn = "Good character",
            themeAr = "حسن الخلق",
            duaAr = "اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ، لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ",
            translationFr = "Ô Allah, guide-moi vers les meilleures mœurs — nul ne guide vers le meilleur sauf Toi — et éloigne de moi les mauvaises — nul ne les éloigne de moi sauf Toi.",
            translationEn = "O Allah, guide me to the best of manners — none guides to the best except You — and keep the worst away from me — none keeps them away except You.",
            source = "Sahih Muslim",
            sourceType = SourceType.HADITH
