            duaAr = "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ",
            translationFr = "Ô Allah, je cherche protection auprès de Toi contre les mauvaises mœurs, les mauvaises actions et les passions blâmables.",
            translationEn = "O Allah, I seek refuge in You from bad manners, bad deeds, and blameworthy desires.",
            source = "Sahih Muslim",
