        ),
        DailyDua(
            id = 190,
            hijriDay = 23,
            hijriMonth = 7,
            occasion = "23 Rajab",
            themeFr = "Protection de la famille",
            themeEn = "Protection of the family",
            themeAr = "حماية الأسرة",
            duaAr = "اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، وَاحْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي",
            translationFr = "Ô Allah, couvre mes défauts, apaise mes frayeurs, et protège-moi de devant, de derrière, de ma droite, de ma gauche et d'en haut. Je cherche protection dans Ta grandeur contre d'être atteint par en dessous.",
            translationEn = "O Allah, cover my faults, calm my fears, and protect me from before me, from behind me, from my right, from my left, and from above. I seek refuge in Your greatness from being struck from beneath.",
            source = "Abou Dawoud",
            sourceType = SourceType.HADITH
        ),
        DailyDua(
            id = 191,
            hijriDay = 24,
            hijriMonth = 7,
            occasion = "24 Rajab",
            themeFr = "Demande de lumière",
            themeEn = "Seeking light",
            themeAr = "طلب النور",
            duaAr = "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ لِي نُورًا",
            translationFr = "Ô Allah, mets une lumière dans mon cœur, dans ma langue, dans mon ouïe, dans ma vue ; à ma droite, à ma gauche, au-dessus de moi, au-dessous de moi, devant moi, derrière moi ; et fais de moi une lumière.",
            translationEn = "O Allah, place light in my heart, in my tongue, in my hearing, in my sight; to my right, to my left, above me, below me, before me, behind me; and make me a light.",
            source = "Sahih Muslim",
            sourceType = SourceType.HADITH
        ),
