            duaAr = "رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي ۖ إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ",
            translationFr = "Seigneur, inspire-moi de Te remercier pour Tes bienfaits envers moi et mes parents, de faire une bonne œuvre qui Te plaît, et accorde la droiture à ma descendance. Je me repens à Toi et je suis parmi les soumis.",
