            themeEn = "Protection from worries",
            themeAr = "الحماية من الهم",
            duaAr = "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ",
            translationFr = "Ô Allah, je cherche protection auprès de Toi contre le souci et la tristesse, l'incapacité et la paresse, l'avarice et la lâcheté, le poids des dettes et la domination des hommes.",
            translationEn = "O Allah, I seek refuge in You from worry and grief, incapacity and laziness, miserliness and cowardice, the burden of debt, and being overpowered by people.",
            source = "Sahih al-Bukhari",
            sourceType = SourceType.HADITH
        ),
