            translationFr = "Ô Allah, prie sur Muhammad et sur la famille de Muhammad comme Tu as prié sur Ibrahim et sur la famille d'Ibrahim, et bénis Muhammad et la famille de Muhammad comme Tu as béni Ibrahim et la famille d'Ibrahim. Tu es Digne de louange, Glorieux.",
            translationEn = "O Allah, send prayers upon Muhammad and upon the family of Muhammad as You sent prayers upon Ibrahim and upon the family of Ibrahim, and bless Muhammad and the family of Muhammad as You blessed Ibrahim and the family of Ibrahim. You are Worthy of praise, Glorious.",
