            themeAr = "دعاء شامل",
            duaAr = "اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ، عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ",
            translationFr = "Ô Allah, je Te demande tout le bien, immédiat et futur, celui que je connais et celui que j'ignore. Et je cherche protection auprès de Toi contre tout le mal, immédiat et futur, celui que je connais et celui que j'ignore.",
            translationEn = "O Allah, I ask You for all good, immediate and future, that which I know and that which I do not know. And I seek refuge in You from all evil, immediate and future, that which I know and that which I do not know.",
            source = "At-Tirmidhi",
            sourceType = SourceType.HADITH
        ),
        DailyDua(
