            themeFr = "Amour d'Allah",
            themeEn = "Love of Allah",
            themeAr = "محبة الله",
            duaAr = "اللَّهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَحُبَّ عَمَلٍ يُقَرِّبُنِي إِلَىٰ حُبِّكَ",
            translationFr = "Ô Allah, je Te demande Ton amour, l'amour de ceux qui T'aiment, et l'amour d'une œuvre qui me rapproche de Ton amour.",
            translationEn = "O Allah, I ask You for Your love, the love of those who love You, and the love of deeds that bring me closer to Your love.",
            source = "At-Tirmidhi",
            sourceType = SourceType.HADITH
