            duaAr = "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ",
            translationFr = "Ô Allah, pardonne-moi tout mon péché : le petit et le grand, le premier et le dernier, celui que j'ai fait ouvertement et celui que j'ai caché.",
