            themeEn = "Love of Allah",
            themeAr = "محبة الله",
            duaAr = "اللَّهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَحُبَّ عَمَلٍ يُقَرِّبُنِي إِلَىٰ حُبِّكَ",
