            themeEn = "End of the year — seeking forgiveness and good",
            themeAr = "ختم السنة — طلب المغفرة والخير",
            duaAr = "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",
            translationFr = "Seigneur, donne-nous belle part ici-bas et belle part dans l'au-delà, et protège-nous du châtiment du Feu.",
            translationEn = "Lord, grant us a good share in this world and a good share in the Hereafter, and protect us from the punishment of the Fire.",
            source = "Coran 2:201",
            sourceType = SourceType.QURAN
        )
    )

    private val byMonthDay: Map<Pair<Int, Int>, DailyDua> =
        all.associateBy { it.hijriMonth to it.hijriDay }

    /** Returns the dua for a Hijri date, or null if not yet in the catalogue. */
    fun forDate(hijriMonth: Int, hijriDay: Int): DailyDua? =
        byMonthDay[hijriMonth to hijriDay]
}
